package listening

import _ "embed"

// scriptPack is the authored listening-script pack
// (flh_listening_script_pack_v1): the 12 written listening scripts of the FLH
// reading/listening workbook v1 with all their questions, generated by
// tools/workbooks (python3 -m flh_workbooks build; `check` fails when it is
// stale). The material is synthetic and unreviewed, written text only: no
// audio, video or timestamp exists. It lives inside the image's build context,
// and the server validates it at startup.
//
//go:embed pack/listening_scripts_v1.json
var scriptPack []byte

// ScriptPack returns the embedded pack JSON.
func ScriptPack() []byte { return scriptPack }
